31	class AscendVidReduction : public arith::IRMutatorWithAnalyzer {
32	public:
33	  static PrimFunc Substitute(PrimFunc f, PassContext ctx) {
34	    arith::Analyzer analyzer;
35	    AscendVidReduction substituter(&analyzer);
36	
37	    PrimFuncNode *fptr = f.CopyOnWrite();
38	
39	    // Apply transformation (buffers_skip_vid_reduction_ collected internally)
40	    fptr->body = substituter.VisitStmt(f->body);
41	
42	    // Store skip buffer names as PrimFunc attrs for downstream passes
43	    // Only set attrs if there are buffers to skip (avoid empty attrs)
44	    if (!substituter.buffers_skip_vid_reduction_.empty()) {
45	      Array<String> skip_buffer_names;
46	      for (const Buffer &buf : substituter.buffers_skip_vid_reduction_) {
47	        skip_buffer_names.push_back(buf->name);
48	      }
49	
50	      Map<String, ObjectRef> attrs_map;
51	      if (fptr->attrs.defined()) {
52	        attrs_map = fptr->attrs->dict;
53	      }
54	      attrs_map.Set("buffers_skip_vid_reduction", skip_buffer_names);
55	      fptr->attrs = DictAttrs(attrs_map);
56	    }
57	
58	    return f;
59	  }
60	
61	private:
62	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
63	
64	  Var vid_;
65	
66	  // The vector number takes the value 2 when cid:vid = 1:2 in vid elimination
67	  // mode
68	  int threads_cnt_ = 1;
69	
70	  // Store the original map and the modified map
71	  std::unordered_map<Buffer, Buffer, ObjectPtrHash, ObjectPtrEqual>
72	      origin_to_new_buffer_;
73	
74	  // Store GM buffer offset info: GM buffer -> UB buffer
75	  std::unordered_map<Buffer, Buffer, ObjectPtrHash, ObjectPtrEqual>
76	      gm_buffer_offset_info_;
77	
78	  // Collect all UB buffers in current Block
79	  std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> ub_buffers_;
80	
81	  // UB buffers that should skip vid reduction (when GM indices contain UB
82	  // BufferLoad)
83	  std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual>
84	      buffers_skip_vid_reduction_;
85	
86	  // Collect current loop variables and their extents
87	  std::vector<std::pair<Var, PrimExpr>> current_loops_;
88	
89	  // Determine if it is a ub buffer
90	  bool IsUbBuffer(const Buffer &buffer) const {
91	    if (buffer->data->type_annotation.defined()) {
92	      if (const auto *ptr_type =
93	              buffer->data->type_annotation.as<PointerTypeNode>()) {
94	        return ptr_type->storage_scope == "shared.ub";
95	      }
96	    }
97	    return false;
98	  }
99	
100	  // Modify buffer shape
101	  Buffer ModifyBufferShape(const Buffer &buffer) {
102	    if (buffer->shape.empty()) {
103	      return buffer;
104	    }
105	    ObjectPtr<BufferNode> new_buffer = make_object<BufferNode>(*buffer.get());
106	
107	    new_buffer->shape = ModifyExtents(buffer->shape);
108	    return Buffer(new_buffer);
109	  }
110	
111	  Array<PrimExpr> ModifyExtents(const Array<PrimExpr> &extents) {
112	    if (extents.empty()) {
113	      return extents;
114	    }
115	    Array<PrimExpr> new_extents;
116	
117	    for (size_t i = 0; i < extents.size(); i++) {
118	      if (i == 0) {
119	        // First dimension divided by 2
120	        PrimExpr first_extent = analyzer_->Simplify(extents[i]);
121	        if (const IntImmNode *int_imm = first_extent.as<IntImmNode>()) {
122	          // Handle constants
123	          int64_t new_value = int_imm->value / 2;
124	          if (new_value < 1) {
125	            new_value = 1;
126	          }
127	          new_extents.push_back(IntImm(first_extent.dtype(), new_value));
128	        } else {
129	          // Complex expression processing
130	          new_extents.push_back(indexdiv(first_extent, 2));
131	        }
132	      } else {
133	        // Other dimensions remain unchanged
134	        new_extents.push_back(VisitExpr(extents[i]));
135	      }
136	    }
137	    return new_extents;
138	  }
139	
140	  // Check if indices directly contain BufferLoad from UB buffers
141	  // BufferLoad appears directly in indices, not nested in expressions
142	  bool IndicesContainUbBufferLoad(
143	      const Array<PrimExpr> &indices,
144	      const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &ub_set) {
145	    for (const PrimExpr &idx : indices) {
146	      if (const auto *load = idx.as<BufferLoadNode>()) {
147	        if (ub_set.count(load->buffer) > 0) {
148	          return true;
149	        }
150	      }
151	    }
152	    return false;
153	  }
154	
155	  // Find loop variable dimension in GM indices (exact match only)
156	  int FindLoopVarDimInGmIndices(const Array<PrimExpr> &indices,
157	                                const Var &loop_var) {
158	    for (size_t i = 0; i < indices.size(); i++) {
159	      if (const VarNode *v = indices[i].as<VarNode>()) {
160	        if (v == loop_var.get()) {
161	          return static_cast<int>(i);
162	        }
163	      }
164	    }
165	    return -1;
166	  }
167	
168	  // Check if GM dimension needs vid offset (loop_extent * threads_cnt <=
169	  // gm_dim_size)
170	  bool GmDimNeedsVidOffset(const PrimExpr &gm_dim_size,
171	                           const PrimExpr &loop_extent) {
172	    PrimExpr total_extent = loop_extent * threads_cnt_;
173	    PrimExpr simplified_total = analyzer_->Simplify(total_extent);
174	    PrimExpr simplified_gm = analyzer_->Simplify(gm_dim_size);
175	
176	    return analyzer_->CanProve(simplified_total <= simplified_gm);
177	  }
