179	  class UbBufferCollector : public StmtExprVisitor {
180	  public:
181	    std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> ub_buffers;
182	    std::function<bool(const Buffer &)> is_ub_checker;
183	
184	    UbBufferCollector(std::function<bool(const Buffer &)> checker)
185	        : is_ub_checker(checker) {}
186	
187	    void VisitStmt_(const BlockNode *op) final {
188	      if (op->alloc_buffers.defined()) {
189	        for (const Buffer &buffer : op->alloc_buffers) {
190	          if (is_ub_checker(buffer)) {
191	            ub_buffers.insert(buffer);
192	          }
193	        }
194	      }
195	      StmtExprVisitor::VisitStmt_(op);
196	    }
197	  };
