199	  class AscendCopyAnalyzer : public StmtExprVisitor {
200	  public:
201	    const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &ub_buffers;
202	    std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual>
203	        &buffers_skip_vid_reduction;
204	    std::function<bool(const Buffer &)> is_ub_checker;
205	    std::function<bool(
206	        const Array<PrimExpr> &,
207	        const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &)>
208	        indices_contain_ub_checker;
209	
210	    AscendCopyAnalyzer(
211	        const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &ubs,
212	        std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &skip_set,
213	        std::function<bool(const Buffer &)> checker,
214	        std::function<bool(
215	            const Array<PrimExpr> &,
216	            const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual> &)>
217	            idx_checker)
218	        : ub_buffers(ubs), buffers_skip_vid_reduction(skip_set),
219	          is_ub_checker(checker), indices_contain_ub_checker(idx_checker) {}
220	
221	    BufferLoad ExtractBufferLoadFromRegion(const Call &region_call) const {
222	      ICHECK(region_call->args.size() >= 1)
223	          << "[Error]<ascend_vid_reduction.cc>: tl.region must have at least 1 "
224	             "arg (BufferLoad)";
225	      const BufferLoadNode *load_node =
226	          region_call->args[0].as<BufferLoadNode>();
227	      ICHECK(load_node != nullptr)
228	          << "[Error]<ascend_vid_reduction.cc>: BufferLoadNode is nullptr";
229	      return GetRef<BufferLoad>(load_node);
230	    }
231	
232	    void VisitExpr_(const CallNode *op) final {
233	      const OpNode *call_op = op->op.as<OpNode>();
234	      if (!call_op || call_op->name != "tl.ascend_copy") {
235	        StmtExprVisitor::VisitExpr_(op);
236	        return;
237	      }
238	
239	      Call src_region = Downcast<Call>(op->args[0]);
240	      Call dst_region = Downcast<Call>(op->args[1]);
241	
242	      // Extract BufferLoad and Buffer from the two regions
243	      BufferLoad src_load = ExtractBufferLoadFromRegion(src_region);
244	      BufferLoad dst_load = ExtractBufferLoadFromRegion(dst_region);
245	      Buffer src_buf = src_load->buffer;
246	      Buffer dst_buf = dst_load->buffer;
247	
248	      bool src_is_ub = is_ub_checker(src_buf);
249	      bool dst_is_ub = is_ub_checker(dst_buf);
250	
251	      if (src_is_ub && !dst_is_ub) {
252	        // UB -> target: src is UB
253	        // Check if target indices contain UB buffer load
254	        if (indices_contain_ub_checker(dst_load->indices, ub_buffers)) {
255	          buffers_skip_vid_reduction.insert(src_buf);
256	        }
257	      } else if (!src_is_ub && dst_is_ub) {
258	        // src -> UB: dst is UB
259	        // Check if src indices contain UB buffer load
260	        if (indices_contain_ub_checker(src_load->indices, ub_buffers)) {
261	          buffers_skip_vid_reduction.insert(dst_buf);
262	        }
263	      }
264	
265	      StmtExprVisitor::VisitExpr_(op);
266	    }
267	  };
268	
269	  bool NeedsVidReduction(const Buffer &buffer) const {
270	    return IsUbBuffer(buffer) && buffers_skip_vid_reduction_.count(buffer) == 0;
271	  }
272	
273	  void AnalyzeBlockBuffers(const Array<Buffer> &alloc_buffers,
274	                           const Stmt &body) {
275	    // First, collect UB buffers from current Block's alloc_buffers
276	    for (const Buffer &buffer : alloc_buffers) {
277	      if (IsUbBuffer(buffer)) {
278	        ub_buffers_.insert(buffer);
279	      }
280	    }
281	
282	    // Also collect UB buffers from nested Blocks in body
283	    UbBufferCollector collector(
284	        [this](const Buffer &b) { return IsUbBuffer(b); });
285	    collector(body);
286	    for (const Buffer &buf : collector.ub_buffers) {
287	      ub_buffers_.insert(buf);
288	    }
289	
290	    // Analyze ascend_copy to find buffers that should skip vid reduction
291	    AscendCopyAnalyzer analyzer(
292	        ub_buffers_, buffers_skip_vid_reduction_,
293	        [this](const Buffer &b) { return IsUbBuffer(b); },
294	        [this](const Array<PrimExpr> &indices,
295	               const std::unordered_set<Buffer, ObjectPtrHash, ObjectPtrEqual>
296	                   &ub_set) {
297	          return IndicesContainUbBufferLoad(indices, ub_set);
298	        });
299	    analyzer(body);
300	  }
301	
302	  Stmt VisitStmt_(const BlockNode *op) override {
303	    if (op->name_hint == "root") {
304	      return IRMutatorWithAnalyzer::VisitStmt_(op);
305	    }
306	    // Non-vid reduce mode and vid number is 2, no custom processing required
307	    if (threads_cnt_ != 2) {
308	      return IRMutatorWithAnalyzer::VisitStmt_(op);
309	    }
310	
311	    AnalyzeBlockBuffers(op->alloc_buffers, op->body);
312	
313	    if (op->alloc_buffers.defined()) {
314	      for (const Buffer &buffer : op->alloc_buffers) {
315	        if (NeedsVidReduction(buffer)) {
316	          Buffer new_buffer = ModifyBufferShape(buffer);
317	          origin_to_new_buffer_[buffer] = new_buffer;
318	        }
319	      }
320	    }
321	
322	    Stmt new_body = this->VisitStmt(op->body);
323	    Array<Buffer> new_alloc_buffers;
324	    if (op->alloc_buffers.defined()) {
325	      for (const Buffer &buffer : op->alloc_buffers) {
326	        auto it = origin_to_new_buffer_.find(buffer);
327	        if (it != origin_to_new_buffer_.end()) {
328	          new_alloc_buffers.push_back(it->second);
329	        } else {
330	          new_alloc_buffers.push_back(buffer);
331	        }
332	      }
333	    }
334	
335	    ObjectPtr<BlockNode> new_block = make_object<BlockNode>(*op);
336	    new_block->body = new_body;
337	    new_block->alloc_buffers = new_alloc_buffers;
338	
339	    // Modify reads/writes BufferRegion for GM buffers
340	    Array<BufferRegion> new_reads = ModifyBufferRegions(op->reads);
341	    Array<BufferRegion> new_writes = ModifyBufferRegions(op->writes);
342	    if (!new_reads.same_as(op->reads)) {
343	      new_block->reads = new_reads;
344	    }
345	    if (!new_writes.same_as(op->writes)) {
346	      new_block->writes = new_writes;
347	    }
348	
349	    return Stmt(new_block);
350	  }
351	
352	  // Modify BufferRegions for GM buffers that have offset info
353	  Array<BufferRegion> ModifyBufferRegions(const Array<BufferRegion> &regions) {
354	    Array<BufferRegion> new_regions = regions;
355	    bool modified = false;
356	
357	    for (size_t i = 0; i < regions.size(); ++i) {
358	      const BufferRegion &region = regions[i];
359	      auto it = gm_buffer_offset_info_.find(region->buffer);
360	      if (it != gm_buffer_offset_info_.end()) {
361	        Buffer ub_buf = it->second;
362	        int ub_dims = ub_buf->shape.size();
363	
364	        // Get modified UB buffer shape, skip if not found
365	        auto ub_it = origin_to_new_buffer_.find(ub_buf);
366	        if (ub_it == origin_to_new_buffer_.end()) {
367	          continue;
368	        }
369	        Buffer modified_ub_buf = ub_it->second;
370	
371	        // Calculate target dimension (same logic as ascend_copy)
372	        int gm_dims = region->region.size();
373	        int target_dim = gm_dims - ub_dims;
374	
375	        Array<Range> new_ranges = region->region;
376	        const Range &old_range = new_ranges[target_dim];
377	        PrimExpr new_min = old_range->min + vid_ * modified_ub_buf->shape[0];
378	        new_ranges.Set(target_dim,
379	                       Range::FromMinExtent(new_min, old_range->extent));
380	
381	        new_regions.Set(i, BufferRegion(region->buffer, new_ranges));
382	        modified = true;
383	      }
384	    }
385	
386	    return modified ? new_regions : regions;
387	  }
388	
389	  BufferLoad ModifyBufferLoadIndices(const BufferLoad &load, size_t ub_dims,
390	                                     const Buffer &ub_buf) {
391	    Buffer buf = load->buffer;
392	    // If it's not a ub buffer, it could be L1/L0C. If it's not a GM buffer, no
393	    // action is needed.
394	    if (buf.scope() != "global") {
395	      return load;
396	    }
397	    auto ub_it = origin_to_new_buffer_.find(ub_buf);
398	    if (ub_it == origin_to_new_buffer_.end()) {
399	      return load;
400	    }
401	    Buffer modified_ub_buf = ub_it->second;
402	
403	    Array<PrimExpr> new_indices;
404	    // 1. Recursively process original indices (sub-expressions included)
405	    for (const PrimExpr &idx : load->indices) {
406	      new_indices.push_back(VisitExpr(idx));
407	    }
408	
409	    // 2. Add vid to the (size - dims)-th dimension
410	    ICHECK(new_indices.size() >= ub_dims)
411	        << "[Error]<ascend_vid_reduction.cc>: ub dims may not be more than gm "
412	           "dims!";
413	    int target_dim = new_indices.size() - ub_dims;
414	    new_indices.Set(
415	        target_dim,
416	        new_indices[target_dim] +
417	            vid_ * modified_ub_buf->shape[0] // Insert vid (vector core ID)
418	    );
419	
420	    // 3. Refactor BufferLoad
421	    return BufferLoad(load->buffer, new_indices);
422	  }
423	
424	  bool ExtentIsEqualOne(const PrimExpr &extent) {
425	    PrimExpr simplified_extent = analyzer_->Simplify(extent);
426	    ICHECK(simplified_extent.defined())
427	        << "[Error]<ascend_vid_reduction.cc>: Fail to simplify the extent."
428	        << "Extent: " << extent;
429	    const IntImmNode *imm = simplified_extent.as<IntImmNode>();
430	    ICHECK(imm != nullptr) << "[Error]<ascend_vid_reduction.cc>: Extent is not "
431	                              "IntImm after simplify."
432	                           << "Extent: " << extent
433	                           << " Simplified extent: " << simplified_extent;
434	    return imm->value == 1;
435	  }
436	
437	  // Extract buffer from access_ptr call argument
438	  // Only check origin_to_new_buffer_ keys (original buffers)
439	  // Note: origin_to_new_buffer_ keys and values share the same data (Var),
440	  // so we can match by buffer.data
441	  Buffer ExtractBufferFromArg(const PrimExpr &arg) const {
442	    if (const CallNode *call = arg.as<CallNode>()) {
443	      if (call->op.same_as(builtin::tvm_access_ptr())) {
444	        // access_ptr args: [access_mask, buffer_data, offset, extent, ...]
445	        // buffer_data is usually at index 1
446	        if (call->args.size() >= 2) {
447	          if (const VarNode *var = call->args[1].as<VarNode>()) {
448	            // Find buffer by data var in origin_to_new_buffer_ keys (original
449	            // buffers)
450	            for (const auto &pair : origin_to_new_buffer_) {
451	              if (pair.first->data.get() == var) {
452	                return pair.first; // Return original buffer
453	              }
454	            }
455	          }
456	        }
457	      }
458	    }
459	    return Buffer();
460	  }
461	
462	  // Check if tvm_access_ptr has offset == 0
463	  bool AccessPtrOffsetIsZero(const PrimExpr &arg) const {
464	    if (const CallNode *call = arg.as<CallNode>()) {
465	      if (call->op.same_as(builtin::tvm_access_ptr())) {
466	        if (call->args.size() >= 3) {
467	          PrimExpr offset = call->args[2];
468	          PrimExpr simplified = analyzer_->Simplify(offset);
469	          if (const IntImmNode *offset_imm = simplified.as<IntImmNode>()) {
470	            return offset_imm->value == 0;
471	          }
472	        }
473	      }
474	    }
475	    return false;
476	  }
477	
478	  // Check if any buffer in the call args is in origin_to_new_buffer_
479	  // AND has offset == 0 (for tvm_access_ptr)
480	  bool HasModifiedBuffer(const CallNode *op) const {
481	    for (const PrimExpr &arg : op->args) {
482	      Buffer buf = ExtractBufferFromArg(arg);
483	      if (buf.defined()) {
484	        auto it = origin_to_new_buffer_.find(buf);
485	        if (it != origin_to_new_buffer_.end()) {
486	          // Check if this arg is tvm_access_ptr with offset == 0
487	          return AccessPtrOffsetIsZero(arg);
488	        }
489	      }
490	    }
491	    return false;
492	  }
