494	  // Check if the operation is a tile op that needs size modification
495	  // Only include operations whose last argument is size calculated from buffer
496	  // shape and has size_0 == size_1 assertion
497	  bool IsTileOp(const std::string &op_name) const {
498	    static const std::set<std::string> tile_ops = {
499	        // binary_op: size = math.prod(dst_extent), assert size_0 == size_1
500	        "tl.ascend_add", "tl.ascend_adds", "tl.ascend_mul", "tl.ascend_muls",
501	        "tl.ascend_sub", "tl.ascend_subs", "tl.ascend_div", "tl.ascend_divs",
502	        "tl.ascend_max", "tl.ascend_maxs", "tl.ascend_min", "tl.ascend_mins",
503	        "tl.ascend_bitwise_and", "tl.ascend_bitwise_or",
504	        // unary_op: size = math.prod(dst_extent), assert size_0 == size_1
505	        "tl.ascend_exp", "tl.ascend_ln", "tl.ascend_abs",
506	        "tl.ascend_reciprocal", "tl.ascend_sqrt", "tl.ascend_rsqrt",
507	        "tl.ascend_relu", "tl.ascend_bitwise_not",
508	        // scalar_op: size = math.prod(src0_extent), assert size_0 == size_2
509	        "tl.ascend_leaky_relu", "tl.ascend_axpy",
510	        // bitwise_shift: size = math.prod(src0_extent), assert size_0 == size_2
511	        "tl.ascend_bitwise_lshift", "tl.ascend_bitwise_rshift",
512	        // compare: dst_size = math.prod(src0_extent)
513	        "tl.ascend_compare", "tl.ascend_compare_scalar",
514	        // sin/cos: size = math.prod(src_extent), assert size_0 == size_2
515	        "tl.ascend_sin", "tl.ascend_cos", "tl.ascend_fill"};
516	    return tile_ops.find(op_name) != tile_ops.end();
517	  }
518	
519	  // Modify the last argument (size) of tile operations
520	  PrimExpr ModifyTileOpSize(const CallNode *op) {
521	    Call tile_call = GetRef<Call>(op);
522	    Array<PrimExpr> new_args = tile_call->args;
523	
524	    // Only modify size if the op involves modified buffer
525	    if (!HasModifiedBuffer(op)) {
526	      return IRMutatorWithAnalyzer::VisitExpr_(op);
527	    }
528	
529	    size_t last_idx = new_args.size() - 1;
530	    PrimExpr last_arg = new_args[last_idx];
531	
532	    PrimExpr simplified = analyzer_->Simplify(last_arg);
533	    if (const IntImmNode *int_imm = simplified.as<IntImmNode>()) {
534	      int64_t new_value = int_imm->value / threads_cnt_;
535	      if (new_value < 1)
536	        new_value = 1;
537	      new_args.Set(last_idx, IntImm(last_arg.dtype(), new_value));
538	    } else {
539	      new_args.Set(last_idx, VisitExpr(indexdiv(last_arg, threads_cnt_)));
540	    }
541	
542	    for (size_t i = 0; i < last_idx; ++i) {
543	      new_args.Set(i, VisitExpr(new_args[i]));
544	    }
545	
546	    return Call(tile_call->dtype, tile_call->op, new_args, tile_call->span);
547	  }
548	
549	  BufferLoad ExtractBufferLoadFromRegion(const Call &region_call) const {
550	    ICHECK(region_call->args.size() >= 1)
551	        << "[Error]<ascend_vid_reduction.cc>: tl.region must have at least 1 "
552	           "arg (BufferLoad)";
553	    const BufferLoadNode *load_node = region_call->args[0].as<BufferLoadNode>();
554	    ICHECK(load_node != nullptr)
555	        << "[Error]<ascend_vid_reduction.cc>: BufferLoadNode is nullptr";
556	    return GetRef<BufferLoad>(load_node);
557	  }
558	
559	  // Modify tl.ascend_reduce: if buffer is vid-reduced, divide M dimension by 2
560	  PrimExpr ModifyAscendReduce(const CallNode *op) {
561	    Call ascend_reduce = GetRef<Call>(op);
562	
563	    // args[0]: string like "reduce_sum<float, 64, 64, -1>"
564	    // args[1]: out_ptr (tvm_access_ptr)
565	    // args[2]: buffer_ptr (tvm_access_ptr)
566	    // args[3]: tmp_ptr (tvm_access_ptr, optional)
567	
568	    // Extract buffer from args[2] (tvm_access_ptr)
569	    Buffer buffer = ExtractBufferFromArg(ascend_reduce->args[2]);
570	
571	    if (!buffer.defined()) {
572	      return IRMutatorWithAnalyzer::VisitExpr_(op);
573	    }
574	
575	    // Check if buffer is vid-reduced (only check origin_to_new_buffer_ keys)
576	    bool buffer_is_vid_reduced = origin_to_new_buffer_.count(buffer) > 0;
577	    if (!buffer_is_vid_reduced) {
578	      return IRMutatorWithAnalyzer::VisitExpr_(op);
579	    }
580	
581	    // Parse string parameter: "reduce_sum<float, 64, 64, -1>"
582	    if (!op->args[0].as<StringImmNode>()) {
583	      return IRMutatorWithAnalyzer::VisitExpr_(op);
584	    }
585	    StringImm param_str = Downcast<StringImm>(op->args[0]);
586	    std::string param = param_str->value;
587	
588	    // Find <...> part
589	    size_t start = param.find('<');
590	    size_t end = param.find('>');
591	    if (start == std::string::npos || end == std::string::npos) {
592	      return IRMutatorWithAnalyzer::VisitExpr_(op);
593	    }
594	
595	    std::string content = param.substr(start + 1, end - start - 1);
596	
597	    // Split by comma: dtype, M, N, dim
598	    std::vector<std::string> parts;
599	    std::stringstream ss(content);
600	    std::string part;
601	    while (std::getline(ss, part, ',')) {
602	      parts.push_back(part);
603	    }
604	
605	    if (parts.size() < 4) {
606	      return IRMutatorWithAnalyzer::VisitExpr_(op);
607	    }
608	
609	    // parts[0]: dtype (e.g., "float")
610	    // parts[1]: M (e.g., "64")
611	    // parts[2]: N (e.g., "64")
612	    // parts[3]: dim (e.g., "-1")
613	
614	    std::string dtype = parts[0];
615	    std::string M_str = parts[1];
616	    std::string N = parts[2];
617	    std::string dim = parts[3];
618	
619	    // Trim leading/trailing spaces
620	    auto trim = [](std::string s) -> std::string {
621	      size_t start = s.find_first_not_of(" \t");
622	      if (start == std::string::npos)
623	        return std::string("");
624	      size_t end = s.find_last_not_of(" \t");
625	      return s.substr(start, end - start + 1);
626	    };
627	    dtype = trim(dtype);
628	    M_str = trim(M_str);
629	    N = trim(N);
630	    dim = trim(dim);
631	
632	    // Try to parse M as integer
633	    long long M;
634	    try {
635	      M = std::stoll(M_str);
636	    } catch (const std::exception &e) {
637	      // M is not an integer (e.g., symbolic variable like "v_block")
638	      // Skip modification for symbolic M
639	      return IRMutatorWithAnalyzer::VisitExpr_(op);
640	    }
641	
642	    // Divide M by 2
643	    long long new_M = M / threads_cnt_;
644	    if (new_M < 1)
645	      new_M = 1;
646	
647	    // Rebuild string: "reduce_sum<float, 32, 64, -1>"
648	    std::string new_param = param.substr(0, start + 1) + dtype + ", " +
649	                            std::to_string(new_M) + ", " + N + ", " + dim + ">";
650	
651	    // Build new Call
652	    Array<PrimExpr> new_args = ascend_reduce->args;
653	    new_args.Set(0, StringImm(new_param));
654	    for (size_t i = 1; i < new_args.size(); ++i) {
655	      new_args.Set(i, VisitExpr(new_args[i]));
656	    }
657	
658	    return Call(ascend_reduce->dtype, ascend_reduce->op, new_args,
659	                ascend_reduce->span);
660	  }
661	
662	  PrimExpr VisitExpr_(const CallNode *op) final {
663	    if (threads_cnt_ != 2) {
664	      return IRMutatorWithAnalyzer::VisitExpr_(op);
665	    }
666	
667	    // Handle tvm_access_ptr: modify extent if buffer is in
668	    // origin_to_new_buffer_
669	    if (op->op.same_as(builtin::tvm_access_ptr())) {
670	      ICHECK_EQ(op->args.size(), 5U);
671	      const VarNode *buffer_var = op->args[1].as<VarNode>();
672	
673	      // Check if this buffer is in origin_to_new_buffer_
674	      Buffer matched_buffer;
675	      for (const auto &pair : origin_to_new_buffer_) {
676	        if (pair.first->data.get() == buffer_var) {
677	          matched_buffer = pair.first;
678	          break;
679	        }
680	      }
681	
682	      if (matched_buffer.defined()) {
683	        // Check offset (args[2]): only modify extent when offset == 0
684	        PrimExpr offset = op->args[2];
685	        PrimExpr simplified_offset = analyzer_->Simplify(offset);
686	        bool offset_is_zero = false;
687	        if (const IntImmNode *offset_imm = simplified_offset.as<IntImmNode>()) {
688	          offset_is_zero = (offset_imm->value == 0);
689	        }
690	
691	        if (!offset_is_zero) {
692	          // offset != 0: accessing different positions in loop, no need to
693	          // modify extent
694	          return IRMutatorWithAnalyzer::VisitExpr_(op);
695	        }
696	
697	        // offset == 0: modify extent (args[3]) by dividing by threads_cnt_
698	        PrimExpr extent = op->args[3];
699	        PrimExpr simplified = analyzer_->Simplify(extent);
700	        PrimExpr new_extent;
701	        if (const IntImmNode *int_imm = simplified.as<IntImmNode>()) {
702	          int64_t new_value = int_imm->value / threads_cnt_;
703	          if (new_value < 1)
704	            new_value = 1;
705	          new_extent = IntImm(extent.dtype(), new_value);
706	        } else {
707	          new_extent = VisitExpr(indexdiv(extent, threads_cnt_));
708	        }
709	
710	        Array<PrimExpr> new_args = op->args;
711	        new_args.Set(3, new_extent);
712	        return Call(op->dtype, op->op, new_args, op->span);
713	      }
714	      return IRMutatorWithAnalyzer::VisitExpr_(op);
715	    }
716	
717	    const OpNode *call_op = op->op.as<OpNode>();
718	    if (!call_op) {
719	      return IRMutatorWithAnalyzer::VisitExpr_(op);
720	    }
721	    std::string op_name = call_op->name;
722	
723	    if (IsTileOp(op_name)) {
724	      return ModifyTileOpSize(op);
725	    }
726	
727	    // Handle tl.ascend_reduce: modify M dimension if buffer is vid-reduced
728	    if (op_name == "tl.ascend_reduce") {
729	      return ModifyAscendReduce(op);
730	    }
731	
732	    if (op_name != "tl.ascend_copy") {
733	      return IRMutatorWithAnalyzer::VisitExpr_(op);
734	    }
735	    Call ascend_copy = GetRef<Call>(op);
736	
737	    // Extract the two tl.region CallNodes for src and dst
738	    Call src_region = Downcast<Call>(ascend_copy->args[0]);
739	    Call dst_region = Downcast<Call>(ascend_copy->args[1]);
740	    ICHECK(Downcast<Op>(src_region->op)->name == "tl.region")
741	        << "args[0] must be tl.region";
742	    ICHECK(Downcast<Op>(dst_region->op)->name == "tl.region")
743	        << "args[1] must be tl.region";
744	
745	    // Extract BufferLoad and Buffer from the two regions
746	    BufferLoad src_load = ExtractBufferLoadFromRegion(src_region);
747	    BufferLoad dst_load = ExtractBufferLoadFromRegion(dst_region);
748	    Buffer src_buf = src_load->buffer;
749	    Buffer dst_buf = dst_load->buffer;
750	
751	    // Check if there is exactly one UB Buffer
752	    bool src_is_ub = IsUbBuffer(src_buf);
753	    bool dst_is_ub = IsUbBuffer(dst_buf);
754	    bool src_was_vid_reduced = origin_to_new_buffer_.count(src_buf) > 0;
755	    bool dst_was_vid_reduced = origin_to_new_buffer_.count(dst_buf) > 0;
756	
757	    // Handle UB -> UB case where both buffers are vid-reduced
758	    if (src_is_ub && dst_is_ub && src_was_vid_reduced && dst_was_vid_reduced) {
759	      int src_dims = src_buf->shape.size();
760	      int dst_dims = dst_buf->shape.size();
761	
762	      // Refactor src UB Region
763	      Array<PrimExpr> src_region_args = src_region->args;
764	      size_t src_target_idx = src_region_args.size() - src_dims;
765	      for (size_t i = 0; i < src_region_args.size(); i++) {
766	        if (i == src_target_idx) {
767	          if (ExtentIsEqualOne(src_region_args[i])) {
768	            src_region_args.Set(i, VisitExpr(src_region_args[i]));
769	          } else {
770	            src_region_args.Set(
771	                i, VisitExpr(indexdiv(src_region_args[i], threads_cnt_)));
772	          }
773	        } else {
774	          src_region_args.Set(i, VisitExpr(src_region_args[i]));
775	        }
776	      }
777	      Call modified_src_region = Call(src_region->dtype, src_region->op,
778	                                      src_region_args, src_region->span);
779	
780	      // Refactor dst UB Region
781	      Array<PrimExpr> dst_region_args = dst_region->args;
782	      size_t dst_target_idx = dst_region_args.size() - dst_dims;
783	      for (size_t i = 0; i < dst_region_args.size(); i++) {
784	        if (i == dst_target_idx) {
785	          if (ExtentIsEqualOne(dst_region_args[i])) {
786	            dst_region_args.Set(i, VisitExpr(dst_region_args[i]));
787	          } else {
788	            dst_region_args.Set(
789	                i, VisitExpr(indexdiv(dst_region_args[i], threads_cnt_)));
790	          }
791	        } else {
792	          dst_region_args.Set(i, VisitExpr(dst_region_args[i]));
793	        }
794	      }
795	      Call modified_dst_region = Call(dst_region->dtype, dst_region->op,
796	                                      dst_region_args, dst_region->span);
797	
798	      // Refactor tl.ascend_copy
799	      Array<PrimExpr> new_copy_args = ascend_copy->args;
800	      new_copy_args.Set(0, modified_src_region);
801	      new_copy_args.Set(1, modified_dst_region);
802	      for (size_t i = 2; i < new_copy_args.size(); ++i) {
803	        new_copy_args.Set(i, VisitExpr(new_copy_args[i]));
804	      }
805	
806	      return Call(ascend_copy->dtype, ascend_copy->op, new_copy_args,
807	                  ascend_copy->span);
808	    }
809	
810	    bool only_one_ub = (src_is_ub && !dst_is_ub) || (!src_is_ub && dst_is_ub);
811	    if (!only_one_ub) {
812	      return IRMutatorWithAnalyzer::VisitExpr_(op);
813	    }
814	    // Locate the non-UB region and modify the indices of its
815	    // BufferLoad
816	    Buffer ub_buf = src_is_ub ? src_buf : dst_buf;
817	    Buffer gm_buf = src_is_ub ? dst_buf : src_buf;
818	    BufferLoad gm_load = src_is_ub ? dst_load : src_load;
819	
820	    bool ub_was_vid_reduced = origin_to_new_buffer_.count(ub_buf) > 0;
821	
822	    bool gm_indices_contain_ub_load =
823	        IndicesContainUbBufferLoad(gm_load->indices, ub_buffers_);
824	
825	    if (gm_indices_contain_ub_load) {
826	      return IRMutatorWithAnalyzer::VisitExpr_(op);
827	    }
828	
829	    // Handle case where UB was not vid-reduced
830	    // Check if GM indices contain loop variable and needs vid offset
831	    if (!ub_was_vid_reduced) {
832	      if (gm_buf.scope() != "global") {
833	        return IRMutatorWithAnalyzer::VisitExpr_(op);
834	      }
835	      Array<PrimExpr> new_gm_indices = gm_load->indices;
836	      bool indices_modified = false;
837	
838	      for (const auto &loop_info : current_loops_) {
839	        Var loop_var = loop_info.first;
840	        PrimExpr loop_extent = loop_info.second;
841	
842	        int dim = FindLoopVarDimInGmIndices(gm_load->indices, loop_var);
843	        if (dim >= 0 && dim < static_cast<int>(gm_buf->shape.size())) {
844	          // Check if loop_extent * threads_cnt <= gm_dim_size
845	          if (GmDimNeedsVidOffset(gm_buf->shape[dim], loop_extent)) {
846	            PrimExpr offset = vid_ * loop_extent;
847	            new_gm_indices.Set(dim, new_gm_indices[dim] + offset);
848	            indices_modified = true;
849	          }
850	        }
851	      }
852	
853	      if (indices_modified) {
854	        BufferLoad modified_gm_load = BufferLoad(gm_buf, new_gm_indices);
855	        gm_buffer_offset_info_[gm_buf] = ub_buf;
856	
857	        // Refactor GM Region
858	        Call gm_region = src_is_ub ? dst_region : src_region;
859	        Array<PrimExpr> gm_region_args = gm_region->args;
860	        gm_region_args.Set(0, VisitExpr(modified_gm_load));
861	        for (size_t i = 1; i < gm_region_args.size(); ++i) {
862	          gm_region_args.Set(i, VisitExpr(gm_region_args[i]));
863	        }
864	        Call modified_gm_region = Call(gm_region->dtype, gm_region->op,
865	                                       gm_region_args, gm_region->span);
866	
867	        // Refactor UB Region (no changes needed since UB was not vid-reduced)
868	        Call ub_region = src_is_ub ? src_region : dst_region;
869	        Array<PrimExpr> ub_region_args = ub_region->args;
870	        for (size_t i = 0; i < ub_region_args.size(); i++) {
871	          ub_region_args.Set(i, VisitExpr(ub_region_args[i]));
872	        }
873	        Call modified_ub_region = Call(ub_region->dtype, ub_region->op,
874	                                       ub_region_args, ub_region->span);
875	
876	        // Refactor tl.ascend_copy
877	        Array<PrimExpr> new_copy_args = ascend_copy->args;
878	        if (src_is_ub) {
879	          new_copy_args.Set(0, modified_ub_region);
880	          new_copy_args.Set(1, modified_gm_region);
881	        } else {
882	          new_copy_args.Set(0, modified_gm_region);
883	          new_copy_args.Set(1, modified_ub_region);
884	        }
885	        for (size_t i = 2; i < new_copy_args.size(); ++i) {
886	          new_copy_args.Set(i, VisitExpr(new_copy_args[i]));
887	        }
888	
889	        return Call(ascend_copy->dtype, ascend_copy->op, new_copy_args,
890	                    ascend_copy->span);
891	      }
892	
893	      return IRMutatorWithAnalyzer::VisitExpr_(op);
894	    }
895	
896	    // Divide the extent at target_idx by threads_cnt_ when it is not 1.
897	    // All other args are just visited.
898	    //   target_idx = static_cast<size_t>(-1) skip extent reduction entirely
899	    //   arg0_override (optional) replaces args[0] (typically a modified
900	    //     BufferLoad) before visiting.
901	    auto reduce_region_extents = [&](const Call &region, size_t target_idx,
902	                                     PrimExpr arg0_override =
903	                                         PrimExpr()) -> Call {
904	      Array<PrimExpr> args = region->args;
905	      for (size_t i = 0; i < args.size(); i++) {
906	        if (i == 0 && arg0_override.defined()) {
907	          args.Set(i, VisitExpr(arg0_override));
908	        } else if (i == target_idx && !ExtentIsEqualOne(args[i])) {
909	          args.Set(i, VisitExpr(indexdiv(args[i], threads_cnt_)));
910	        } else {
911	          args.Set(i, VisitExpr(args[i]));
912	        }
913	      }
914	      return Call(region->dtype, region->op, args, region->span);
915	    };
916	
917	    int ub_dims = ub_buf->shape.size();
918	    BufferLoad modified_load =
919	        ModifyBufferLoadIndices(gm_load, ub_dims, ub_buf);
920	
921	    // Record GM buffer offset info for later use in BlockNode reads/writes
922	    gm_buffer_offset_info_[gm_buf] = ub_buf;
923	
924	    // If it's not a UB buffer, it could be L1/L0C.
925	    // If it's not a GM buffer, no action is needed.
926	    Call target_region = src_is_ub ? dst_region : src_region;
927	    size_t target_idx = (gm_buf.scope() == "global")
928	                            ? (target_region->args.size() - ub_dims)
929	                            : static_cast<size_t>(-1);
930	    Call modified_region =
931	        reduce_region_extents(target_region, target_idx, modified_load);
932	
933	    // Refactor UB Region
934	    Call ub_region = src_is_ub ? src_region : dst_region;
935	    size_t ub_target_idx = ub_region->args.size() - ub_dims;
936	    Call modified_ub_region = reduce_region_extents(ub_region, ub_target_idx);
937	
938	    // Refactor tl.ascend_copy
939	    Array<PrimExpr> new_copy_args = ascend_copy->args;
940	    if (src_is_ub) {
941	      new_copy_args.Set(0, VisitExpr(modified_ub_region)); // replace ub region
942	      new_copy_args.Set(1, VisitExpr(modified_region)); // replace target region
943	    } else {
944	      new_copy_args.Set(0, VisitExpr(modified_region));    // replace src region
945	      new_copy_args.Set(1, VisitExpr(modified_ub_region)); // replace ub region
946	    }
947	
948	    for (size_t i = 2; i < new_copy_args.size(); ++i) {
949	      new_copy_args.Set(i, VisitExpr(new_copy_args[i]));
950	    }
951	
952	    if (new_copy_args.size() > 5) {
953	      auto tmp_expr = ascend_copy->args[5];
954	      if (auto *tmp_call = tmp_expr.as<CallNode>();
955	          tmp_call && Downcast<Op>(tmp_call->op)->name == "tl.region") {
956	        Call tmp_region = Downcast<Call>(tmp_expr);
957	        BufferLoad tmp_load = ExtractBufferLoadFromRegion(tmp_region);
958	        if (IsUbBuffer(tmp_load->buffer) &&
959	            origin_to_new_buffer_.count(tmp_load->buffer) > 0) {
960	          int tmp_dims = tmp_load->buffer->shape.size();
961	          size_t tmp_target_idx = tmp_region->args.size() - tmp_dims;
962	          Call reduced_tmp = reduce_region_extents(tmp_region, tmp_target_idx);
963	          new_copy_args.Set(5, VisitExpr(reduced_tmp));
964	        }
965	      }
966	    }
967	
968	    return Call(ascend_copy->dtype, ascend_copy->op, new_copy_args,
969	                ascend_copy->span);
970	  }
971	
972	  PrimExpr VisitExpr_(const BufferLoadNode *op) final {
973	    auto it = origin_to_new_buffer_.find(op->buffer);
974	    Array<PrimExpr> new_indices;
975	    for (const PrimExpr &idx : op->indices) {
976	      new_indices.push_back(VisitExpr(idx));
977	    }
978	    if (it != origin_to_new_buffer_.end()) {
979	      return BufferLoad(it->second, new_indices);
980	    }
981	    return BufferLoad(op->buffer, new_indices);
982	  }
983	
984	  Stmt VisitStmt_(const BufferStoreNode *op) final {
985	    auto it = origin_to_new_buffer_.find(op->buffer);
986	    PrimExpr new_value = VisitExpr(op->value);
987	    Array<PrimExpr> new_indices;
988	    for (const PrimExpr &idx : op->indices) {
989	      new_indices.push_back(VisitExpr(idx));
990	    }
991	    if (it != origin_to_new_buffer_.end()) {
992	      return BufferStore(it->second, new_value, new_indices);
993	    }
994	    return BufferStore(op->buffer, new_value, new_indices);
995	  }
996	
997	  // Check if loop variable is used in vid-reduced UB buffer's first dimension
998	  // Analyze ORIGINAL body, check ORIGINAL buffers (keys in
999	  // origin_to_new_buffer_) Two cases:
1000	  // 1. Loop var directly used as first index in BufferLoad/BufferStore
1001	  // 2. Loop var used in tvm_access_ptr offset where offset/extent = loop_var
1002	  bool LoopVarUsedInVidReducedUbFirstDim(const Var &loop_var,
1003	                                         const Stmt &body) {
1004	    class LoopVarAnalyzer : public StmtExprVisitor {
1005	    public:
1006	      Var target_var;
1007	      arith::Analyzer *analyzer;
1008	      const std::unordered_map<Buffer, Buffer, ObjectPtrHash, ObjectPtrEqual>
1009	          &origin_to_new_buffer;
1010	      bool found = false;
1011	
1012	      LoopVarAnalyzer(const Var &var, arith::Analyzer *a,
1013	                      const std::unordered_map<Buffer, Buffer, ObjectPtrHash,
1014	                                               ObjectPtrEqual> &buffers)
1015	          : target_var(var), analyzer(a), origin_to_new_buffer(buffers) {}
1016	
1017	      void VisitExpr_(const BufferLoadNode *op) final {
1018	        if (origin_to_new_buffer.count(op->buffer) > 0) {
1019	          if (!op->indices.empty()) {
1020	            const PrimExpr &first_idx = op->indices[0];
1021	            if (const VarNode *v = first_idx.as<VarNode>()) {
1022	              if (v == target_var.get()) {
1023	                found = true;
1024	                return;
1025	              }
1026	            }
1027	          }
1028	        }
1029	        StmtExprVisitor::VisitExpr_(op);
1030	      }
1031	
1032	      void VisitStmt_(const BufferStoreNode *op) final {
1033	        if (origin_to_new_buffer.count(op->buffer) > 0) {
1034	          if (!op->indices.empty()) {
1035	            const PrimExpr &first_idx = op->indices[0];
1036	            if (const VarNode *v = first_idx.as<VarNode>()) {
1037	              if (v == target_var.get()) {
1038	                found = true;
1039	                return;
1040	              }
1041	            }
1042	          }
1043	        }
1044	        StmtExprVisitor::VisitStmt_(op);
1045	      }
1046	
1047	      void VisitExpr_(const CallNode *op) final {
1048	        // Handle tvm_access_ptr: check if offset/extent equals loop_var
1049	        if (!op->op.same_as(builtin::tvm_access_ptr()) || op->args.size() < 4) {
1050	          StmtExprVisitor::VisitExpr_(op);
1051	          return;
1052	        }
1053	
1054	        // Extract buffer from args[1] (buffer_data)
1055	        const VarNode *buffer_var = op->args[1].as<VarNode>();
1056	        if (!buffer_var) {
1057	          StmtExprVisitor::VisitExpr_(op);
1058	          return;
1059	        }
1060	
1061	        // Find buffer in origin_to_new_buffer
1062	        Buffer buffer;
1063	        for (const auto &pair : origin_to_new_buffer) {
1064	          if (pair.first->data.get() == buffer_var) {
1065	            buffer = pair.first;
1066	            break;
1067	          }
1068	        }
1069	
1070	        // buffer.defined() implies buffer is vid-reduced UB (checked
1071	        // during BlockNode processing)
1072	        if (!buffer.defined()) {
1073	          StmtExprVisitor::VisitExpr_(op);
1074	          return;
1075	        }
1076	
1077	        // Get offset and extent from access_ptr
1078	        PrimExpr offset = op->args[2];
1079	        PrimExpr extent = op->args[3];
1080	
1081	        PrimExpr simplified_extent = analyzer->Simplify(extent);
1082	        const IntImmNode *extent_imm = simplified_extent.as<IntImmNode>();
1083	        if (!extent_imm || extent_imm->value == 0) {
1084	          StmtExprVisitor::VisitExpr_(op);
1085	          return;
1086	        }
1087	
1088	        // Check if offset / extent simplifies to loop_var
1089	        PrimExpr division = analyzer->Simplify(indexdiv(offset, extent));
1090	        const VarNode *v = division.as<VarNode>();
1091	        if (v && v == target_var.get()) {
1092	          found = true;
1093	          return;
1094	        }
1095	
1096	        StmtExprVisitor::VisitExpr_(op);
1097	      }
1098	    };
1099	
1100	    LoopVarAnalyzer analyzer(loop_var, analyzer_, origin_to_new_buffer_);
1101	    analyzer(body);
1102	    return analyzer.found;
1103	  }
1104	
1105	  Stmt VisitStmt_(const ForNode *op) final {
1106	    if (threads_cnt_ == 2) {
1107	      // Step 1: Analyze whether vid reduction is needed (analyze original body)
1108	      bool need_reduce =
1109	          LoopVarUsedInVidReducedUbFirstDim(op->loop_var, op->body);
1110	
1111	      // Step 2: Calculate the correct extent
1112	      PrimExpr effective_extent = op->extent;
1113	      if (need_reduce) {
1114	        PrimExpr simplified = analyzer_->Simplify(op->extent);
1115	        if (const IntImmNode *int_imm = simplified.as<IntImmNode>()) {
1116	          int64_t new_value = int_imm->value / threads_cnt_;
1117	          if (new_value < 1)
1118	            new_value = 1;
1119	          effective_extent = IntImm(op->extent.dtype(), new_value);
1120	        } else {
1121	          effective_extent = indexdiv(op->extent, threads_cnt_);
1122	        }
1123	
1124	        // Step 3: Only add vid-reduced loops to current_loops_
1125	        current_loops_.push_back({op->loop_var, effective_extent});
1126	      }
1127	
1128	      // Step 4: Process the loop body
1129	      Stmt new_body = VisitStmt(op->body);
1130	
1131	      // Step 5: Pop on exit (if previously pushed)
1132	      if (need_reduce) {
1133	        current_loops_.pop_back();
1134	      }
1135	
1136	      // Step 6: Return the new ForNode
1137	      return For(op->loop_var, op->min, effective_extent, op->kind, new_body,
1138	                 op->thread_binding, op->annotations);
1139	    }
1140	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1141	  }
1142	
1143	  Stmt VisitStmt_(const AttrStmtNode *op) final {
1144	    if (op->attr_key == tvm::tir::attr::thread_extent) {
1145	      if (const IterVarNode *iter_var_node = op->node.as<IterVarNode>()) {
1146	        IterVar iter_var = GetRef<IterVar>(iter_var_node);
1147	        if (iter_var->thread_tag == "threadIdx.x") {
1148	          vid_ = iter_var->var;
1149	          threads_cnt_ = Downcast<IntImm>(op->value)->value;
1150	        }
1151	      }
1152	    }
1153	    return IRMutatorWithAnalyzer::VisitStmt_(op);
1154	  }
1155	};
1156	
1157	tvm::transform::Pass AscendVidReduction() {
1158	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1159	    auto new_func = AscendVidReduction::Substitute(std::move(f), ctx);
1160	    return new_func;
1161	  };
1162	  return CreatePrimFuncPass(pass_func, 0, "tl.AscendVidReduction", {});
1163	}
1164	
1165	// regist host path
1166	TVM_REGISTER_GLOBAL("tl.transform.AscendVidReduction")
1167	    .set_body_typed(AscendVidReduction);
1168	
1169	} // namespace tl
1170	} // namespace tvm
